using Microsoft.EntityFrameworkCore;
using YoutubeStudio.Api.Models;

namespace YoutubeStudio.Api.Data;

public sealed class YoutubeStudioDbContext(DbContextOptions<YoutubeStudioDbContext> options) : DbContext(options)
{
    public DbSet<User> Users => Set<User>();
    public DbSet<Membership> Memberships => Set<Membership>();
    public DbSet<Workspace> Workspaces => Set<Workspace>();
    public DbSet<Channel> Channels => Set<Channel>();
    public DbSet<ChannelDna> ChannelDnas => Set<ChannelDna>();
    public DbSet<Opportunity> Opportunities => Set<Opportunity>();
    public DbSet<ResearchProject> ResearchProjects => Set<ResearchProject>();
    public DbSet<ResearchSource> ResearchSources => Set<ResearchSource>();
    public DbSet<ResearchEvidence> ResearchEvidence => Set<ResearchEvidence>();
    public DbSet<ResearchClaim> ResearchClaims => Set<ResearchClaim>();
    public DbSet<ResearchClaimEvidence> ResearchClaimEvidence => Set<ResearchClaimEvidence>();
    public DbSet<ResearchBrief> ResearchBriefs => Set<ResearchBrief>();
    public DbSet<VideoProject> VideoProjects => Set<VideoProject>();
    public DbSet<ProductionJob> ProductionJobs => Set<ProductionJob>();
    public DbSet<ProductionArtifact> ProductionArtifacts => Set<ProductionArtifact>();
    public DbSet<ProductionCost> ProductionCosts => Set<ProductionCost>();
    public DbSet<ContentGenome> ContentGenomes => Set<ContentGenome>();
    public DbSet<VideoOutcome> VideoOutcomes => Set<VideoOutcome>();
    public DbSet<AuditEvent> AuditEvents => Set<AuditEvent>();
    public DbSet<DomainEvent> DomainEvents => Set<DomainEvent>();
    public DbSet<ProviderUsage> ProviderUsages => Set<ProviderUsage>();
    public DbSet<Experiment> Experiments => Set<Experiment>();
    public DbSet<RevenueEvent> RevenueEvents => Set<RevenueEvent>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasPostgresExtension("vector");
        modelBuilder.Entity<User>(entity => { entity.ToTable("users"); entity.HasKey(x => x.Id).HasName("pk_users"); entity.Property(x => x.Email).HasMaxLength(320).IsRequired(); entity.Property(x => x.PasswordHash).HasMaxLength(500).IsRequired(); entity.Property(x => x.DisplayName).HasMaxLength(200); entity.HasIndex(x => x.Email).IsUnique().HasDatabaseName("ix_users_email"); });
        modelBuilder.Entity<Membership>(entity => { entity.ToTable("memberships"); entity.HasKey(x => x.Id).HasName("pk_memberships"); entity.Property(x => x.Role).HasConversion<string>().HasMaxLength(50).IsRequired(); entity.HasOne(x => x.User).WithMany(x => x.Memberships).HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.Workspace).WithMany().HasForeignKey(x => x.WorkspaceId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.UserId, x.WorkspaceId }).IsUnique().HasDatabaseName("ix_memberships_user_id_workspace_id"); entity.HasIndex(x => x.WorkspaceId).HasDatabaseName("ix_memberships_workspace_id"); });
        modelBuilder.Entity<Workspace>(entity => { entity.ToTable("workspaces"); entity.HasKey(x => x.Id).HasName("pk_workspaces"); entity.Property(x => x.Name).HasMaxLength(200).IsRequired(); entity.HasIndex(x => x.Name).HasDatabaseName("ix_workspaces_name"); });
        modelBuilder.Entity<Channel>(entity => { entity.ToTable("channels"); entity.HasKey(x => x.Id).HasName("pk_channels"); entity.Property(x => x.Name).HasMaxLength(200).IsRequired(); entity.Property(x => x.Platform).HasMaxLength(50).IsRequired(); entity.Property(x => x.Niche).HasMaxLength(500); entity.Property(x => x.Audience).HasMaxLength(2000); entity.Property(x => x.Language).HasMaxLength(20).HasDefaultValue("en"); entity.Property(x => x.Goals).HasMaxLength(4000); entity.HasOne(x => x.Workspace).WithMany(x => x.Channels).HasForeignKey(x => x.WorkspaceId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.WorkspaceId, x.Name }).HasDatabaseName("ix_channels_workspace_id_name"); });
        modelBuilder.Entity<ChannelDna>(entity => { entity.ToTable("channel_dna"); entity.HasKey(x => x.Id).HasName("pk_channel_dna"); entity.Property(x => x.Audience).HasMaxLength(4000); entity.Property(x => x.Positioning).HasMaxLength(4000); entity.Property(x => x.Tone).HasMaxLength(2000); entity.Property(x => x.VisualLanguage).HasMaxLength(4000); entity.Property(x => x.RecurringFormats).HasMaxLength(8000); entity.Property(x => x.ForbiddenPatterns).HasMaxLength(8000); entity.Property(x => x.StrategicGoals).HasMaxLength(8000); entity.HasOne(x => x.Channel).WithMany().HasForeignKey(x => x.ChannelId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.ChannelId, x.Version }).IsUnique().HasDatabaseName("ix_channel_dna_channel_id_version"); });
        modelBuilder.Entity<Opportunity>(entity => { entity.ToTable("opportunities"); entity.HasKey(x => x.Id).HasName("pk_opportunities"); entity.Property(x => x.Title).HasMaxLength(500).IsRequired(); entity.Property(x => x.Status).HasMaxLength(50).IsRequired(); entity.Property(x => x.OpportunityScore).HasPrecision(5, 2); entity.Property(x => x.RevenueScore).HasPrecision(5, 2); entity.HasOne(x => x.Workspace).WithMany(x => x.Opportunities).HasForeignKey(x => x.WorkspaceId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.WorkspaceId, x.Status }).HasDatabaseName("ix_opportunities_workspace_id_status"); });
        modelBuilder.Entity<ResearchProject>(entity => { entity.ToTable("research_projects"); entity.HasKey(x => x.Id).HasName("pk_research_projects"); entity.Property(x => x.Status).HasMaxLength(50).IsRequired(); entity.HasOne(x => x.Opportunity).WithMany().HasForeignKey(x => x.OpportunityId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.WorkspaceId, x.CreatedAtUtc }).HasDatabaseName("ix_research_projects_workspace_id_created_at"); entity.HasIndex(x => x.OpportunityId).IsUnique(); });
        modelBuilder.Entity<ResearchSource>(entity => { entity.ToTable("research_sources"); entity.HasKey(x => x.Id).HasName("pk_research_sources"); entity.Property(x => x.Url).HasMaxLength(2048).IsRequired(); entity.Property(x => x.Title).HasMaxLength(500).IsRequired(); entity.Property(x => x.MetadataJson).HasMaxLength(200000).IsRequired(); entity.HasOne(x => x.ResearchProject).WithMany(x => x.Sources).HasForeignKey(x => x.ResearchProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.ResearchProjectId, x.CreatedAtUtc }).HasDatabaseName("ix_research_sources_project_id_created_at"); entity.HasIndex(x => new { x.WorkspaceId, x.ResearchProjectId }).HasDatabaseName("ix_research_sources_workspace_id_project_id"); });
        modelBuilder.Entity<ResearchEvidence>(entity => { entity.ToTable("research_evidence"); entity.HasKey(x => x.Id).HasName("pk_research_evidence"); entity.Property(x => x.Quote).HasMaxLength(20000).IsRequired(); entity.Property(x => x.Locator).HasMaxLength(1000); entity.Property(x => x.Context).HasMaxLength(10000); entity.Property(x => x.MetadataJson).HasMaxLength(200000).IsRequired(); entity.HasOne(x => x.ResearchSource).WithMany(x => x.Evidence).HasForeignKey(x => x.ResearchSourceId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.ResearchSourceId, x.CreatedAtUtc }).HasDatabaseName("ix_research_evidence_source_id_created_at"); entity.HasIndex(x => new { x.WorkspaceId, x.ResearchSourceId }).HasDatabaseName("ix_research_evidence_workspace_id_source_id"); });
        modelBuilder.Entity<ResearchClaim>(entity => { entity.ToTable("research_claims"); entity.HasKey(x => x.Id).HasName("pk_research_claims"); entity.Property(x => x.Text).HasMaxLength(20000).IsRequired(); entity.Property(x => x.VerificationStatus).HasMaxLength(50).IsRequired(); entity.Property(x => x.MetadataJson).HasMaxLength(200000).IsRequired(); entity.HasOne(x => x.ResearchProject).WithMany().HasForeignKey(x => x.ResearchProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.WorkspaceId, x.ResearchProjectId }).HasDatabaseName("ix_research_claims_workspace_id_project_id"); entity.HasIndex(x => x.ResearchProjectId).HasDatabaseName("IX_research_claims_ResearchProjectId"); });
        modelBuilder.Entity<ResearchClaimEvidence>(entity => { entity.ToTable("research_claim_evidence"); entity.HasKey(x => new { x.ResearchClaimId, x.ResearchEvidenceId }).HasName("pk_research_claim_evidence"); entity.HasOne(x => x.ResearchClaim).WithMany(x => x.EvidenceLinks).HasForeignKey(x => x.ResearchClaimId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.ResearchEvidence).WithMany(x => x.ClaimLinks).HasForeignKey(x => x.ResearchEvidenceId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => x.ResearchEvidenceId).HasDatabaseName("ix_research_claim_evidence_evidence_id"); });
        modelBuilder.Entity<ResearchBrief>(entity => { entity.ToTable("research_briefs"); entity.HasKey(x => x.Id).HasName("pk_research_briefs"); entity.Property(x => x.Markdown).HasMaxLength(200000).IsRequired(); entity.Property(x => x.Status).HasMaxLength(50).IsRequired(); entity.HasOne(x => x.ResearchProject).WithOne(x => x.Brief).HasForeignKey<ResearchBrief>(x => x.ResearchProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => x.ResearchProjectId).IsUnique().HasDatabaseName("ix_research_briefs_project_id"); entity.HasIndex(x => new { x.WorkspaceId, x.ResearchProjectId }).HasDatabaseName("ix_research_briefs_workspace_id_project_id"); });
        modelBuilder.Entity<VideoProject>(entity => { entity.ToTable("video_projects"); entity.HasKey(x => x.Id); entity.Property(x => x.Prompt).HasMaxLength(10000).IsRequired(); entity.Property(x => x.Title).HasMaxLength(500); entity.Property(x => x.Script).HasMaxLength(100000); entity.Property(x => x.Status).HasConversion<string>().HasMaxLength(50).IsRequired(); entity.Property(x => x.RequiresAiDisclosure).HasDefaultValue(true); entity.HasOne(x => x.Workspace).WithMany().HasForeignKey(x => x.WorkspaceId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.Channel).WithMany().HasForeignKey(x => x.ChannelId).OnDelete(DeleteBehavior.SetNull); entity.HasIndex(x => new { x.WorkspaceId, x.Status }); });
        modelBuilder.Entity<ProductionJob>(entity => { entity.ToTable("production_jobs"); entity.HasKey(x => x.Id); entity.Property(x => x.Status).HasConversion<string>().HasMaxLength(50).IsRequired(); entity.Property(x => x.Error).HasMaxLength(4000); entity.Property(x => x.LastCompletedStage).HasMaxLength(50); entity.Property(x => x.IdempotencyKey).HasMaxLength(200); entity.HasOne(x => x.VideoProject).WithMany().HasForeignKey(x => x.VideoProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.VideoProjectId, x.CreatedAtUtc }); entity.HasIndex(x => x.IdempotencyKey).HasDatabaseName("ix_production_jobs_idempotency_key"); });
        modelBuilder.Entity<ProductionArtifact>(entity => { entity.ToTable("production_artifacts"); entity.HasKey(x => x.Id); entity.Property(x => x.Type).HasConversion<string>().HasMaxLength(50).IsRequired(); entity.Property(x => x.Version).HasDefaultValue(1); entity.Property(x => x.ProviderAssetId).HasMaxLength(500).IsRequired(); entity.Property(x => x.Content).HasMaxLength(200000); entity.Property(x => x.MetadataJson).HasMaxLength(200000); entity.HasOne(x => x.VideoProject).WithMany().HasForeignKey(x => x.VideoProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.VideoProjectId, x.Type, x.Version }); });
        modelBuilder.Entity<ProductionCost>(entity => { entity.ToTable("production_costs"); entity.HasKey(x => x.Id); entity.Property(x => x.Stage).HasMaxLength(50).IsRequired(); entity.Property(x => x.Provider).HasMaxLength(200).IsRequired(); entity.Property(x => x.Units).HasPrecision(18, 4); entity.Property(x => x.UnitCostUsd).HasPrecision(18, 6); entity.Property(x => x.TotalCostUsd).HasPrecision(18, 6); entity.HasOne(x => x.VideoProject).WithMany().HasForeignKey(x => x.VideoProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.VideoProjectId, x.Stage }); });
        modelBuilder.Entity<ContentGenome>(entity => { entity.ToTable("content_genomes"); entity.HasKey(x => x.Id); entity.Property(x => x.Title).HasMaxLength(500).IsRequired(); entity.Property(x => x.AttributesJson).HasMaxLength(200000).IsRequired(); entity.HasOne(x => x.VideoProject).WithMany().HasForeignKey(x => x.VideoProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => x.VideoProjectId).IsUnique(); });
        modelBuilder.Entity<VideoOutcome>(entity => { entity.ToTable("video_outcomes"); entity.HasKey(x => x.Id); entity.Property(x => x.Source).HasMaxLength(100).IsRequired(); entity.Property(x => x.EstimatedRevenueUsd).HasPrecision(18, 6); entity.HasOne(x => x.VideoProject).WithMany().HasForeignKey(x => x.VideoProjectId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.VideoProjectId, x.MeasuredAtUtc }); });
        modelBuilder.Entity<AuditEvent>(entity => { entity.ToTable("audit_events"); entity.HasKey(x => x.Id); entity.Property(x => x.Action).HasMaxLength(100).IsRequired(); entity.Property(x => x.Actor).HasMaxLength(200).IsRequired(); entity.Property(x => x.DetailsJson).HasMaxLength(200000); entity.HasIndex(x => new { x.WorkspaceId, x.CreatedAtUtc }); entity.HasIndex(x => new { x.VideoProjectId, x.CreatedAtUtc }); });
        modelBuilder.Entity<DomainEvent>(entity => { entity.ToTable("domain_events"); entity.HasKey(x => x.Id); entity.Property(x => x.Type).HasMaxLength(100).IsRequired(); entity.Property(x => x.Payload).HasMaxLength(200000); entity.HasIndex(x => new { x.WorkspaceId, x.OccurredAtUtc }); entity.HasIndex(x => new { x.AggregateId, x.OccurredAtUtc }); entity.HasIndex(x => x.Type); });
        modelBuilder.Entity<RevenueEvent>(entity => { entity.ToTable("revenue_events"); entity.HasKey(x => x.Id); entity.Property(x => x.Source).HasMaxLength(50).IsRequired(); entity.Property(x => x.AmountUsd).HasPrecision(18, 4); entity.Property(x => x.Cta).HasMaxLength(500); entity.HasIndex(x => new { x.WorkspaceId, x.OccurredAtUtc }); entity.HasIndex(x => new { x.VideoProjectId, x.OccurredAtUtc }); });
        modelBuilder.Entity<Experiment>(entity => { entity.ToTable("experiments"); entity.HasKey(x => x.Id); entity.Property(x => x.Variable).HasMaxLength(100).IsRequired(); entity.Property(x => x.Hypothesis).HasMaxLength(4000).IsRequired(); entity.Property(x => x.SuccessMetric).HasMaxLength(100).IsRequired(); entity.Property(x => x.DecisionRule).HasMaxLength(4000); entity.Property(x => x.Status).HasConversion<string>().HasMaxLength(50).IsRequired(); entity.Property(x => x.Outcome).HasMaxLength(4000); entity.HasIndex(x => new { x.WorkspaceId, x.CreatedAtUtc }); });
        modelBuilder.Entity<ProviderUsage>(entity => { entity.ToTable("provider_usage"); entity.HasKey(x => x.Id); entity.Property(x => x.Provider).HasMaxLength(200).IsRequired(); entity.Property(x => x.Model).HasMaxLength(200).IsRequired(); entity.Property(x => x.TaskType).HasMaxLength(50).IsRequired(); entity.Property(x => x.Currency).HasMaxLength(10).IsRequired(); entity.Property(x => x.InputUnits).HasPrecision(18, 4); entity.Property(x => x.OutputUnits).HasPrecision(18, 4); entity.Property(x => x.UnitPriceUsd).HasPrecision(18, 6); entity.Property(x => x.TotalCostUsd).HasPrecision(18, 6); entity.HasIndex(x => new { x.WorkspaceId, x.CreatedAtUtc }); entity.HasIndex(x => new { x.VideoProjectId, x.CreatedAtUtc }); entity.HasIndex(x => x.Provider); });
    }
}